import{_ as o,a0 as i,w as r,s as d,ao as l,I as t,x as s,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"服務端 I/O 性能：Node、PHP、Java、Go 的對比 | LCTT x X-CMD","titleTemplate":false,"description":"服務端 I/O 性能：Node、PHP、Java、Go 的對比 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"服務端 I/O 性能：Node、PHP、Java、Go 的對比 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"服務端 I/O 性能：Node、PHP、Java、Go 的對比 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170109 Server-side IO Performance Node vs. PHP vs. Java vs. Go","title":"服務端 I/O 性能：Node、PHP、Java、Go 的對比","tag":"201710","desc":""},"relativePath":"201710/20170109 Server-side IO Performance Node vs. PHP vs. Java vs. Go.md","filePath":"[post].md"}'),c={name:"201710/20170109 Server-side IO Performance Node vs. PHP vs. Java vs. Go.md"};function g(h,a,b,u,m,P){const e=i("Link");return r(),d("div",null,[a[28]||(a[28]=l('<h1 id="服務端-i-o-性能-node、php、java、go-的對比" tabindex="-1">服務端 I/O 性能：Node、PHP、Java、Go 的對比 <a class="header-anchor" href="#服務端-i-o-性能-node、php、java、go-的對比" aria-label="Permalink to “服務端 I/O 性能：Node、PHP、Java、Go 的對比”">​</a></h1><p>瞭解應用程序的輸入/輸出（I/O）模型意味着理解應用程序處理其數據的載入差異，並揭示其在真實環境中表現。或許你的應用程序很小，在不承受很大的負載時，這並不是個嚴重的問題；但隨着應用程序的流量負載增加，可能因為使用了低效的 I/O 模型導致承受不了而崩潰。</p><p>和大多數情況一樣，處理這種問題的方法有多種方式，這不僅僅是一個擇優的問題，而是對權衡的理解問題。 接下來我們來看看 I/O 到底是什麼。</p><p><img src="https://uploads.toptal.io/blog/image/123050/toptal-blog-image-1494506620527-88162414141f3b3627e6f8dacbea29f0.jpg" alt="Cover Photo: Server-side I/O: Node vs. PHP vs. Java vs. Go"></p><p>在本文中，我們將對 Node、Java、Go 和 PHP + Apache 進行對比，討論不同語言如何構造其 I/O ，每個模型的優缺點，並總結一些基本的規律。如果你擔心你的下一個 Web 應用程序的 I/O 性能，本文將給你最優的解答。</p><h3 id="i-o-基礎知識-快速複習" tabindex="-1">I/O 基礎知識: 快速複習 <a class="header-anchor" href="#i-o-基礎知識-快速複習" aria-label="Permalink to “I/O 基礎知識: 快速複習”">​</a></h3><p>要了解 I/O 所涉及的因素，我們首先深入到操作系統層面複習這些概念。雖然看起來並不與這些概念直接打交道，但你會一直通過應用程序的運行時環境與它們間接接觸。瞭解細節很重要。</p><h4 id="系統調用" tabindex="-1">系統調用 <a class="header-anchor" href="#系統調用" aria-label="Permalink to “系統調用”">​</a></h4><p>首先是系統調用，其被描述如下：</p><ul><li>程序（所謂“<ruby>用户端<rt>user land</rt></ruby>”）必須請求操作系統內核代表它執行 I/O 操作。</li><li>“<ruby>系統調用<rt>syscall</rt></ruby>”是你的程序要求內核執行某些操作的方法。這些實現的細節在操作系統之間有所不同，但基本概念是相同的。有一些具體的指令會將控制權從你的程序轉移到內核（類似函數調用，但是使用專門用於處理這種情況的專用方式）。一般來説，系統調用會被阻塞，這意味着你的程序會等待內核返回（控制權到）你的代碼。</li><li>內核在所需的物理設備（ 磁盤、網卡等 ）上執行底層 I/O 操作，並回應系統調用。在實際情況中，內核可能需要做許多事情來滿足你的要求，包括等待設備準備就緒、更新其內部狀態等，但作為應用程序開發人員，你不需要關心這些。這是內核的工作。</li></ul><p><img src="https://uploads.toptal.io/blog/image/123021/toptal-blog-image-1494484316720-491f79a78eb5c6c419aec0971955cc31.jpg" alt="Syscalls Diagram"></p><h4 id="阻塞與非阻塞" tabindex="-1">阻塞與非阻塞 <a class="header-anchor" href="#阻塞與非阻塞" aria-label="Permalink to “阻塞與非阻塞”">​</a></h4><p>上面我們提到過，系統調用是阻塞的，一般來説是這樣的。然而，一些調用被歸類為“非阻塞”，這意味着內核會接收你的請求，將其放在隊列或緩衝區之類的地方，然後立即返回而不等待實際的 I/O 發生。所以它只是在很短的時間內“阻塞”，只需要排隊你的請求即可。</p><p>舉一些 Linux 系統調用的例子可能有助於理解：</p><ul><li><code>read()</code> 是一個阻塞調用 - 你傳遞一個句柄，指出哪個文件和緩衝區在哪裏傳送它所讀取的數據，當數據就緒時，該調用返回。這種方式的優點是簡單友好。</li><li>分別調用 <code>epoll_create()</code>、<code>epoll_ctl()</code> 和 <code>epoll_wait()</code> ，你可以創建一組句柄來偵聽、添加/刪除該組中的處理程序、然後阻塞直到有任何事件發生。這允許你通過單個線程有效地控制大量的 I/O 操作，但是現在談這個還太早。如果你需要這個功能當然好，但須知道它使用起來是比較複雜的。</li></ul><p>瞭解這裏的時間差異的數量級是很重要的。假設 CPU 內核運行在 3GHz，在沒有進行 CPU 優化的情況下，那麼它每秒執行 30 億次<ruby>週期<rt>cycle</rt></ruby>（即每納秒 3 個週期）。非阻塞系統調用可能需要幾十個週期來完成，或者説 “相對少的納秒” 時間完成。而一個被跨網絡接收信息所阻塞的系統調用可能需要更長的時間 - 例如 200 毫秒（1/5 秒）。這就是説，如果非阻塞調用需要 20 納秒，阻塞調用需要 2 億納秒。你的進程因阻塞調用而等待了 1000 萬倍的時長！</p><p><img src="https://uploads.toptal.io/blog/image/123022/toptal-blog-image-1494484326798-0372c535867b3c829329692d3b8a1a21.jpg" alt="Blocking vs. Non-blocking Syscalls"></p><p>內核既提供了阻塞 I/O （“從網絡連接讀取並給出數據”），也提供了非阻塞 I/O （“告知我何時這些網絡連接具有新數據”）的方法。使用的是哪種機制對調用進程的阻塞時長有截然不同的影響。</p><h4 id="調度" tabindex="-1">調度 <a class="header-anchor" href="#調度" aria-label="Permalink to “調度”">​</a></h4><p>關鍵的第三件事是當你有很多線程或進程開始阻塞時會發生什麼。</p><p>根據我們的理解，線程和進程之間沒有很大的區別。在現實生活中，最顯著的性能相關的差異在於，由於線程共享相同的內存，而進程每個都有自己的內存空間，使得單獨的進程往往佔用更多的內存。但是當我們談論<ruby>調度<rt>Scheduling</rt></ruby>時，它真正歸結為一類事情（線程和進程類同），每個都需要在可用的 CPU 內核上獲得一段執行時間。如果你有 300 個線程運行在 8 個內核上，則必須將時間分成幾份，以便每個線程和進程都能分享它，每個運行一段時間，然後交給下一個。這是通過 “<ruby>上下文切換<rt>context switch</rt></ruby>” 完成的，可以使 CPU 從運行到一個線程/進程到切換下一個。</p><p>這些上下文切換也有相關的成本 - 它們需要一些時間。在某些快速的情況下，它可能小於 100 納秒，但根據實際情況、處理器速度/體系結構、CPU 緩存等，偶見花費 1000 納秒或更長時間。</p><p>而線程（或進程）越多，上下文切換就越多。當我們涉及數以千計的線程時，每個線程花費數百納秒，就會變得很慢。</p><p>然而，非阻塞調用實質上是告訴內核“僅在這些連接之一有新的數據或事件時再叫我”。這些非阻塞調用旨在有效地處理大量 I/O 負載並減少上下文交換。</p><p>這些你明白了麼？現在來到了真正有趣的部分：我們來看看一些流行的語言對那些工具的使用，並得出關於易用性和性能之間權衡的結論，以及一些其他有趣小東西。</p><p>聲明，本文中顯示的示例是零碎的（片面的，只能體現相關的信息）; 資料庫訪問、外部緩存系統（ memcache 等等）以及任何需要 I/O 的東西都將執行某種類型的 I/O 調用，其實質與上面所示的簡單示例效果相同。此外，對於將 I/O 描述為“阻塞”（ PHP、Java ）的情況，HTTP 請求和響應讀取和寫入本身就是阻塞調用：系統中隱藏着更多 I/O 及其伴生的性能問題需要考慮。</p><p>為一個項目選擇編程語言要考慮很多因素。甚至當你只考慮效率時，也有很多因素。但是，如果你擔心你的程序將主要受到 I/O 的限制，如果 I/O 性能影響到項目的成敗，那麼這些是你需要了解的。</p><h3 id="保持簡單-方法-php" tabindex="-1">“保持簡單”方法：PHP <a class="header-anchor" href="#保持簡單-方法-php" aria-label="Permalink to ““保持簡單”方法：PHP”">​</a></h3>',28)),t("p",null,[a[1]||(a[1]=s("早在 90 年代，很多人都穿着 ",-1)),n(e,{href:"https://www.pinterest.com/pin/414401603185852181/"},{default:p(()=>[...a[0]||(a[0]=[s("Converse",-1)])]),_:1}),a[2]||(a[2]=s(" 鞋，用 Perl 寫着 CGI 腳本。然後 PHP 來了，就像一些人喜歡咒罵的一樣，它使得動態網頁更容易。",-1))]),a[29]||(a[29]=l(`<p>PHP 使用的模型相當簡單。雖有一些出入，但你的 PHP 服務器基本上是這樣：</p><p>HTTP 請求來自用户的瀏覽器，並訪問你的 Apache Web 服務器。Apache 為每個請求創建一個單獨的進程，有一些優化方式可以重新使用它們，以最大限度地減少創建次數（ 相對而言，創建進程較慢 ）。Apache 調用 PHP 並告訴它運行磁盤上合適的 <code>.php</code> 文件。PHP 代碼執行並阻塞 I/O 調用。你在 PHP 中調用 <code>file_get_contents()</code> ，其底層會調用 <code>read()</code> 系統調用並等待結果。</p><p>當然，實際的代碼是直接嵌入到你的頁面，並且該操作被阻塞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// blocking file I/O</span></span>
<span class="line"><span>$file_data = file_get_contents(‘/path/to/file.dat’);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// blocking network I/O</span></span>
<span class="line"><span>$curl = curl_init(&#39;http://example.com/example-microservice&#39;);</span></span>
<span class="line"><span>$result = curl_exec($curl);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// some more blocking network I/O</span></span>
<span class="line"><span>$result = $db-&gt;query(&#39;SELECT id, data FROM examples ORDER BY id DESC limit 100&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>?&gt;</span></span></code></pre></div><p>關於如何與系統集成，就像這樣：</p><p><img src="https://uploads.toptal.io/blog/image/123049/toptal-blog-image-1494505840356-b8a0d78356a18a040600cad68d52b7ae.jpg" alt="I/O Model PHP"></p><p>很簡單：每個請求一個進程。 I/O 調用就阻塞。優點是簡單可工作，缺點是，同時與 20,000 個客户端連接，你的服務器將會崩潰。這種方法不能很好地擴展，因為內核提供的用於處理大容量 I/O （epoll 等） 的工具沒有被使用。 雪上加霜的是，為每個請求運行一個單獨的進程往往會使用大量的系統資源，特別是內存，這通常是你在這樣的場景中遇到的第一個問題。</p><p><em>注意：Ruby 使用的方法與 PHP 非常相似，在大致的方面上，它們可以被認為是相同的。</em></p><h3 id="多線程方法-java" tabindex="-1">多線程方法： Java <a class="header-anchor" href="#多線程方法-java" aria-label="Permalink to “多線程方法： Java”">​</a></h3><p>就在你購買你的第一個域名，在某個句子後很酷地隨機説出 “dot com” 的那個時候，Java 來了。而 Java 具有內置於該語言中的多線程功能，它非常棒（特別是在創建時）。</p><p>大多數 Java Web 服務器通過為每個請求啓動一個新的執行線程，然後在該線程中最終調用你（作為應用程序開發人員）編寫的函數。</p><p>在 Java Servlet 中執行 I/O 往往看起來像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public void doGet(HttpServletRequest request,</span></span>
<span class="line"><span>	HttpServletResponse response) throws ServletException, IOException</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	// blocking file I/O</span></span>
<span class="line"><span>	InputStream fileIs = new FileInputStream(&quot;/path/to/file&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	// blocking network I/O</span></span>
<span class="line"><span>	URLConnection urlConnection = (new URL(&quot;http://example.com/example-microservice&quot;)).openConnection();</span></span>
<span class="line"><span>	InputStream netIs = urlConnection.getInputStream();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	// some more blocking network I/O</span></span>
<span class="line"><span>out.println(&quot;...&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>由於我們上面的 <code>doGet</code> 方法對應於一個請求，並且在其自己的線程中運行，而不是每個請求一個單獨的進程，申請自己的內存。這樣有一些好處，比如在線程之間共享狀態、緩存數據等，因為它們可以訪問彼此的內存，但是它與調度的交互影響與之前的 PHP 的例子幾乎相同。每個請求獲得一個新線程，該線程內的各種 I/O 操作阻塞在線程內，直到請求被完全處理為止。線程被池化以最小化創建和銷燬它們的成本，但是數千個連接仍然意味着數千個線程，這對調度程序是不利的。</p><p>重要的里程碑出現在 Java 1.4 版本（以及 1.7 的重要升級）中，它獲得了執行非阻塞 I/O 調用的能力。大多數應用程序、web 應用和其它用途不會使用它，但至少它是可用的。一些 Java Web 服務器嘗試以各種方式利用這一點；然而，絕大多數部署的 Java 應用程序仍然如上所述工作。</p><p><img src="https://uploads.toptal.io/blog/image/123024/toptal-blog-image-1494484354611-f68fb1694b52ffd8ea112ec2fb5570c0.jpg" alt="I/O Model Java"></p><p>肯定有一些很好的開箱即用的 I/O 功能，Java 讓我們更接近，但它仍然沒有真正解決當你有一個大量的 I/O 綁定的應用程序被數千個阻塞線程所壓垮的問題。</p><h3 id="無阻塞-i-o-作為一等公民-node" tabindex="-1">無阻塞 I/O 作為一等公民： Node <a class="header-anchor" href="#無阻塞-i-o-作為一等公民-node" aria-label="Permalink to “無阻塞 I/O 作為一等公民： Node”">​</a></h3><p>當更好的 I/O 模式來到 Node.js，阻塞才真正被解決。任何一個曾聽過 Node 簡單介紹的人都被告知這是“非阻塞”，可以有效地處理 I/O。這在一般意義上是正確的。但在細節中則不盡然，而且當在進行性能工程時，這種巫術遇到了問題。</p><p>Node 實現的範例基本上不是説 “在這裏寫代碼來處理請求”，而是説 “在這裏寫代碼來<strong>開始</strong>處理請求”。每次你需要做一些涉及到 I/O 的操作，你會創建一個請求並給出一個回調函數，Node 將在完成之後調用該函數。</p><p>在請求中執行 I/O 操作的典型 Node 代碼如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http.createServer(function(request, response) {</span></span>
<span class="line"><span>	fs.readFile(&#39;/path/to/file&#39;, &#39;utf8&#39;, function(err, data) {</span></span>
<span class="line"><span>		response.end(data);</span></span>
<span class="line"><span>	});</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>你可以看到，這裏有兩個回調函數。當請求開始時，第一個被調用，當文件數據可用時，第二個被調用。</p><p>這樣做的基本原理是讓 Node 有機會有效地處理這些回調之間的 I/O 。一個更加密切相關的場景是在 Node 中進行資料庫調用，但是我不會在這個例子中囉嗦，因為它遵循完全相同的原則：啓動資料庫調用，並給 Node 一個回調函數，它使用非阻塞調用單獨執行 I/O 操作，然後在你要求的數據可用時調用回調函數。排隊 I/O 調用和讓 Node 處理它然後獲取回調的機制稱為“事件循環”。它工作的很好。</p><p><img src="https://uploads.toptal.io/blog/image/123025/toptal-blog-image-1494484364927-0869f1e8acd49501f676dffef7f3c642.jpg" alt="I/O Model Node.js"></p><p>然而，這個模型有一個陷阱，究其原因，很多是與 V8 JavaScript 引擎（Node 用的是 Chrome 瀏覽器的 JS 引擎）如何實現的有關^注1 。你編寫的所有 JS 代碼都運行在單個線程中。你可以想想，這意味着當使用高效的非阻塞技術執行 I/O 時，你的 JS 可以在單個線程中運行計算密集型的操作，每個代碼塊都會阻塞下一個。可能出現這種情況的一個常見例子是以某種方式遍歷資料庫記錄，然後再將其輸出到客户端。這是一個示例，展示了其是如何工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var handler = function(request, response) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	connection.query(&#39;SELECT ...&#39;, function (err, rows) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		if (err) { throw err };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		for (var i = 0; i &lt; rows.length; i++) {</span></span>
<span class="line"><span>			// do processing on each row</span></span>
<span class="line"><span>		}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>		response.end(...); // write out the results</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>};</span></span></code></pre></div><p>雖然 Node 確實有效地處理了 I/O ，但是上面的例子中 <code>for</code> 循環是在你的唯一的一個主線程中佔用 CPU 週期。這意味着如果你有 10,000 個連接，則該循環可能會使你的整個應用程序像爬行般緩慢，具體取決於其會持續多久。每個請求必須在主線程中分享一段時間，一次一段。</p><p>這整個概念的前提是 I/O 操作是最慢的部分，因此最重要的是要有效地處理這些操作，即使這意味着要連續進行其他處理。這在某些情況下是正確的，但不是全部。</p><p>另一點是，雖然這只是一個觀點，但是寫一堆嵌套的回調可能是相當令人討厭的，有些則認為它使代碼更難以追蹤。在 Node 代碼中看到回調嵌套 4 層、5 層甚至更多層並不罕見。</p><p>我們再次來權衡一下。如果你的主要性能問題是 I/O，則 Node 模型工作正常。然而，它的關鍵是，你可以在一個處理 HTTP 請求的函數里面放置 CPU 密集型的代碼，而且不小心的話會導致每個連接都很慢。</p><h3 id="最自然的非阻塞-go" tabindex="-1">最自然的非阻塞：Go <a class="header-anchor" href="#最自然的非阻塞-go" aria-label="Permalink to “最自然的非阻塞：Go”">​</a></h3><p>在我進入 Go 部分之前，我應該披露我是一個 Go 的粉絲。我已經在許多項目中使用過它，我是一個其生產力優勢的公開支持者，我在我的工作中使用它。</p><p>那麼，讓我們來看看它是如何處理 I/O 的。Go 語言的一個關鍵特徵是它包含自己的調度程序。在 Go 中，不是每個執行線程對應於一個單一的 OS 線程，其通過一種叫做 “<ruby>協程<rt>goroutine</rt></ruby>” 的概念來工作。而 Go 的運行時可以將一個協程分配給一個 OS 線程，使其執行或暫停它，並且它不與一個 OS 線程相關聯——這要基於那個協程正在做什麼。來自 Go 的 HTTP 服務器的每個請求都在單獨的協程中處理。</p><p>調度程序的工作原理如圖所示：</p><p><img src="https://uploads.toptal.io/blog/image/123026/toptal-blog-image-1494484377088-fdcc99ced01713937ff76afc9b56416c.jpg" alt="I/O Model Go"></p><p>在底層，這是通過 Go 運行時中的各個部分實現的，它通過對請求的寫入/讀取/連接等操作來實現 I/O 調用，將當前協程休眠，並當採取進一步動作時喚醒該協程。</p><p>從效果上看，Go 運行時做的一些事情與 Node 做的沒有太大不同，除了回調機制是內置到 I/O 調用的實現中，並自動與調度程序交互。它也不會受到必須讓所有處理程序代碼在同一個線程中運行的限制，Go 將根據其調度程序中的邏輯自動將協程映射到其認為適當的 OS 線程。結果是這樣的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>func ServeHTTP(w http.ResponseWriter, r *http.Request) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	// the underlying network call here is non-blocking</span></span>
<span class="line"><span>	rows, err := db.Query(&quot;SELECT ...&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	for _, row := range rows {</span></span>
<span class="line"><span>		// do something with the rows,</span></span>
<span class="line"><span>// each request in its own goroutine</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	w.Write(...) // write the response, also non-blocking</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如上所述，我們重構基本的代碼結構為更簡化的方式，並在底層仍然實現了非阻塞 I/O。</p><p>在大多數情況下，最終是“兩全其美”的。非阻塞 I/O 用於所有重要的事情，但是你的代碼看起來像是阻塞，因此更容易理解和維護。Go 調度程序和 OS 調度程序之間的交互處理其餘部分。這不是完整的魔法，如果你建立一個大型系統，那麼值得我們來看看有關它的工作原理的更多細節；但與此同時，你獲得的“開箱即用”的環境可以很好地工作和擴展。</p><p>Go 可能有其缺點，但一般來説，它處理 I/O 的方式不在其中。</p><h3 id="謊言-可惡的謊言和基準" tabindex="-1">謊言，可惡的謊言和基準 <a class="header-anchor" href="#謊言-可惡的謊言和基準" aria-label="Permalink to “謊言，可惡的謊言和基準”">​</a></h3><p>對這些各種模式的上下文切換進行準確的定時是很困難的。我也可以認為這對你來説不太有用。相反，我會給出一些比較這些服務器環境的整個 HTTP 服務器性能的基本基準。請記住，影響整個端到端 HTTP 請求/響應路徑的性能有很多因素，這裏提供的數字只是我將一些樣本放在一起進行基本比較的結果。</p><p>對於這些環境中的每一個，我寫了適當的代碼在一個 64k 文件中讀取隨機字節，在其上運行了一個 SHA-256 哈希 N 次（ N 在 URL 的查詢字符串中指定，例如 .../test.php?n=100），並打印出結果十六進制散列。我選擇這樣做，是因為使用一些一致的 I/O 和受控的方式來運行相同的基準測試是一個增加 CPU 使用率的非常簡單的方法。</p>`,45)),t("p",null,[a[4]||(a[4]=s("有關使用的環境的更多細節，請參閲 ",-1)),n(e,{href:"https://peabody.io/post/server-env-benchmarks/"},{default:p(()=>[...a[3]||(a[3]=[s("基準説明",-1)])]),_:1}),a[5]||(a[5]=s(" 。",-1))]),a[30]||(a[30]=l('<p>首先，我們來看一些低併發的例子。運行 2000 次迭代，300 個併發請求，每個請求只有一個散列（N = 1），結果如下：</p><p><img src="https://uploads.toptal.io/blog/image/123027/toptal-blog-image-1494484391296-b9fa90935e5892036d8e30b4950ed448.jpg" alt="Mean number of milliseconds to complete a request across all concurrent requests, N=1"></p><p><em>時間是在所有併發請求中完成請求的平均毫秒數。越低越好。</em></p><p>僅從一張圖很難得出結論，但是對我來説，似乎在大量的連接和計算量上，我們看到時間更多地與語言本身的一般執行有關，對於 I/O 更是如此。請注意，那些被視為“腳本語言”的語言（鬆散類型，動態解釋）執行速度最慢。</p><p>但是，如果我們將 N 增加到 1000，仍然有 300 個併發請求，相同的任務，但是哈希迭代是 1000 倍（顯着增加了 CPU 負載）：</p><p><img src="https://uploads.toptal.io/blog/image/123028/toptal-blog-image-1494484399553-e808d736ed165a362c8ad101a9486fe5.jpg" alt="Mean number of milliseconds to complete a request across all concurrent requests, N=1000"></p><p><em>時間是在所有併發請求中完成請求的平均毫秒數。越低越好。</em></p><p>突然間， Node 性能顯著下降，因為每個請求中的 CPU 密集型操作都相互阻塞。有趣的是，在這個測試中，PHP 的性能要好得多（相對於其他的），並且打敗了 Java。（值得注意的是，在 PHP 中，SHA-256 實現是用 C 編寫的，在那個循環中執行路徑花費了更多的時間，因為現在我們正在進行 1000 個哈希迭代）。</p><p>現在讓我們嘗試 5000 個併發連接（N = 1） - 或者是我可以發起的最大連接。不幸的是，對於大多數這些環境，故障率並不顯着。對於這個圖表，我們來看每秒的請求總數。 <em>越高越好</em> :</p><p><img src="https://uploads.toptal.io/blog/image/123029/toptal-blog-image-1494484407612-527f9a22d54c1d30738d7cd3fe41e415.jpg" alt="Total number of requests per second, N=1, 5000 req/sec"></p><p><em>每秒請求數。越高越好。</em></p><p>這個圖看起來有很大的不同。我猜測，但是看起來像在高連接量時，產生新進程所涉及的每連接開銷以及與 PHP + Apache 相關聯的附加內存似乎成為主要因素，並阻止了 PHP 的性能。顯然，Go 是這裏的贏家，其次是 Java，Node，最後是 PHP。</p><p>雖然與你的整體吞吐量相關的因素很多，並且在應用程序之間也有很大的差異，但是你對底層發生什麼的事情以及所涉及的權衡瞭解更多，你將會得到更好的結果。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>以上所有這一切，很顯然，隨着語言的發展，處理大量 I/O 的大型應用程序的解決方案也隨之發展。</p>',15)),t("p",null,[a[10]||(a[10]=s("為了公平起見，PHP 和 Java，儘管這篇文章中的描述，確實 ",-1)),n(e,{href:"http://reactphp.org/"},{default:p(()=>[...a[6]||(a[6]=[s("實現了",-1)])]),_:1}),a[11]||(a[11]=s(" 在 ",-1)),n(e,{href:"https://netty.io/"},{default:p(()=>[...a[7]||(a[7]=[s(" web 應用程序",-1)])]),_:1}),a[12]||(a[12]=s(" 中 ",-1)),n(e,{href:"http://undertow.io/"},{default:p(()=>[...a[8]||(a[8]=[s("可使用的",-1)])]),_:1}),a[13]||(a[13]=s()),n(e,{href:"http://amphp.org/"},{default:p(()=>[...a[9]||(a[9]=[s(" 非阻塞 I/O",-1)])]),_:1}),a[14]||(a[14]=s(" 。但是這些方法並不像上述方法那麼常見，並且需要考慮使用這種方法來維護服務器的隨之而來的操作開銷。更不用説你的代碼必須以與這些環境相適應的方式進行結構化；你的 “正常” PHP 或 Java Web 應用程序通常不會在這樣的環境中進行重大修改。",-1))]),a[31]||(a[31]=l('<p>作為比較，如果我們考慮影響性能和易用性的幾個重要因素，我們得出以下結論：</p><div class="table-wrap"><table><thead><tr><th>語言</th><th>線程與進程</th><th>非阻塞 I/O</th><th>使用便捷性</th></tr></thead><tbody><tr><td>PHP</td><td>進程</td><td>否</td><td></td></tr><tr><td>Java</td><td>線程</td><td>可用</td><td>需要回調</td></tr><tr><td>Node.js</td><td>線程</td><td>是</td><td>需要回調</td></tr><tr><td>Go</td><td>線程 （協程）</td><td>是</td><td>不需要回調</td></tr></tbody></table></div><p>線程通常要比進程有更高的內存效率，因為它們共享相同的內存空間，而進程則沒有。結合與非阻塞 I/O 相關的因素，我們可以看到，至少考慮到上述因素，當我們從列表往下看時，與 I/O 相關的一般設置得到改善。所以如果我不得不在上面的比賽中選擇一個贏家，那肯定會是 Go。</p><p>即使如此，在實踐中，選擇構建應用程序的環境與你的團隊對所述環境的熟悉程度以及你可以實現的總體生產力密切相關。因此，每個團隊都深入並開始在 Node 或 Go 中開發 Web 應用程序和服務可能就沒有意義。事實上，尋找開發人員或你內部團隊的熟悉度通常被認為是不使用不同語言和/或環境的主要原因。也就是説，過去十五年來，時代已經發生了變化。</p><p>希望以上內容可以幫助你更清楚地瞭解底層發生的情況，併為你提供如何處理應用程序的現實可擴展性的一些想法。</p><hr>',6)),t("p",null,[a[16]||(a[16]=s("via: ",-1)),n(e,{href:"https://www.toptal.com/back-end/server-side-io-performance-node-php-java-go"},{default:p(()=>[...a[15]||(a[15]=[s("https://www.toptal.com/back-end/server-side-io-performance-node-php-java-go",-1)])]),_:1})]),t("p",null,[a[20]||(a[20]=s("作者：",-1)),n(e,{href:"https://www.toptal.com/resume/brad-peabody"},{default:p(()=>[...a[17]||(a[17]=[s("BRAD PEABODY",-1)])]),_:1}),a[21]||(a[21]=s(" 譯者：",-1)),n(e,{href:"https://github.com/MonkeyDEcho"},{default:p(()=>[...a[18]||(a[18]=[s("MonkeyDEcho",-1)])]),_:1}),a[22]||(a[22]=s(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...a[19]||(a[19]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[25]||(a[25]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...a[23]||(a[23]=[s("LCTT",-1)])]),_:1}),a[26]||(a[26]=s(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:p(()=>[...a[24]||(a[24]=[s("Linux中國",-1)])]),_:1}),a[27]||(a[27]=s(" 榮譽推出",-1))])])}const O=o(c,[["render",g]]);export{v as __pageData,O as default};
